using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Default options with the reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false when metadata is unavailable
//    Use an empty resolver so nothing is resolvable.
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => throw new NotSupportedException() }
    }
};

bool found = restrictedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine($"\nTryGetTypeInfo on restricted options: found={found}, result={probed?.Type.Name ?? "(null)"}");

// Also show the happy-path probe
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed2);
Console.WriteLine($"TryGetTypeInfo on normal options:     found={found2}, result={probed2?.Type.Name ?? "(null)"}");

record Person(string Name, int Age);

